script:
(function () {
  'use strict';
  // Two paychecks side by side, each with its own pay, Form W-4 entries and deductions (2026 rules).
  //   Taxable wages per check = gross - pre-tax 401(k) - cafeteria-plan benefits
  //   Federal withholding     = IRS Pub. 15-T (2026) Worksheet 1A, Annual Percentage Method tables:
  //     adjusted = max(0, wages x periods + Step 4(a) - Step 4(b) - (Step 2 box ? 0 : $12,900 MFJ /
  //     $8,600 otherwise)); annual = C + D x (adjusted - A); per check = max(0, annual / periods -
  //     Step 3 / periods) + Step 4(c)
  //   Social Security 6.2% of yearly FICA wages up to the wage base; Medicare 1.45% plus 0.9% above
  //   $200,000 a year; both shown per check as the yearly amount / periods. 401(k) stays FICA-taxable.
  //   State tax = flat rate x taxable wages. Take-home = gross - every deduction.
  // Checked in Node (b8pay/tests/pdc.test.js): biweekly $2,000 single, no deductions -> withholding
  //   $156.15 (52,000 - 8,600 = 43,400; 1,240 + 12% x 23,500 = 4,060 / 26), the same figure as the
  //   W-4 calculator and the Pub. 15-T biweekly wage bracket row (Single $156); $2,500 biweekly at
  //   5% vs 10% 401(k) (+$125 a check saved) -> take-home falls by $125 - 12% x $125 - 4% x $125 =
  //   $105.00 (withholding -$15, state tax -$5); $10,000 weekly -> Social Security $11,439 a year ($184,500 x 6.2%), Medicare $7,540 +
  //   0.9% x $320,000 = $10,420 a year.
  //
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Withholding tables: IRS Publication 15-T (2026), Annual Percentage Method tables for automated
  //   payroll systems, rows [A at least, C tentative amount, D rate]; Worksheet 1A line 1g.
  // Social Security wage base $184,500 and rates: SSA 2026 COLA fact sheet. Medicare and the
  //   0.9% Additional Medicare Tax above $200,000: IRC 3101(b), 3102(f).
  var TAX_YEAR = 2026;
  var STANDARD = {
    mfj: [[0, 0, 0], [19300, 0, 0.10], [44100, 2480, 0.12], [120100, 11600, 0.22], [230700, 35932, 0.24],
          [422850, 82048, 0.32], [531750, 116896, 0.35], [788000, 206583.50, 0.37]],
    single: [[0, 0, 0], [7500, 0, 0.10], [19900, 1240, 0.12], [57900, 5800, 0.22], [113200, 17966, 0.24],
             [209275, 41024, 0.32], [263725, 58448, 0.35], [648100, 192979.25, 0.37]],
    hoh: [[0, 0, 0], [15550, 0, 0.10], [33250, 1770, 0.12], [83000, 7740, 0.22], [121250, 16155, 0.24],
          [217300, 39207, 0.32], [271750, 56631, 0.35], [656150, 191171, 0.37]]
  };
  var CHECKBOX = {
    mfj: [[0, 0, 0], [16100, 0, 0.10], [28500, 1240, 0.12], [66500, 5800, 0.22], [121800, 17966, 0.24],
          [217875, 41024, 0.32], [272325, 58448, 0.35], [400450, 103291.75, 0.37]],
    single: [[0, 0, 0], [8050, 0, 0.10], [14250, 620, 0.12], [33250, 2900, 0.22], [60900, 8983, 0.24],
             [108938, 20512, 0.32], [136163, 29224, 0.35], [328350, 96489.63, 0.37]],
    hoh: [[0, 0, 0], [12075, 0, 0.10], [20925, 885, 0.12], [45800, 3870, 0.22], [64925, 8077.50, 0.24],
          [112950, 19603.50, 0.32], [140175, 28315.50, 0.35], [332375, 95585.50, 0.37]]
  };
  var LINE_1G = { mfj: 12900, single: 8600, hoh: 8600 };
  var SS_RATE = 0.062, SS_WAGE_BASE = 184500;
  var MEDICARE_RATE = 0.0145, ADDL_MEDICARE_RATE = 0.009, ADDL_MEDICARE_START = 200000;
  // ---------------------------------------------------------------------------------------

  // --- calc start
  function withholding(wages, periods, w) {
    var adjusted = Math.max(0, wages * periods + w.step4a - w.step4b - (w.step2 ? 0 : LINE_1G[w.status]));
    var table = (w.step2 ? CHECKBOX : STANDARD)[w.status], row = table[0];
    for (var i = 0; i < table.length; i++) if (adjusted >= table[i][0]) row = table[i];
    var annual = row[1] + row[2] * (adjusted - row[0]);
    return { perCheck: Math.max(0, annual / periods - w.step3 / periods) + w.step4c, rate: row[2] };
  }

  // s: gross, status, step2, step3, step4a, step4b, step4c, k401Pct, pretax, post, stateRate (per check)
  function paycheck(s, periods) {
    var k401 = s.gross * s.k401Pct / 100;
    var pretax = Math.min(s.pretax, Math.max(0, s.gross - k401));
    var wages = Math.max(0, s.gross - k401 - pretax);
    var w = withholding(wages, periods, s);
    var ficaYear = Math.max(0, s.gross - pretax) * periods;
    var ssYear = SS_RATE * Math.min(ficaYear, SS_WAGE_BASE);
    var medYear = MEDICARE_RATE * ficaYear + ADDL_MEDICARE_RATE * Math.max(0, ficaYear - ADDL_MEDICARE_START);
    var state = s.stateRate / 100 * wages;
    var r = { gross: s.gross, k401: k401, pretax: pretax, wages: wages, fed: w.perCheck, rate: w.rate,
              ss: ssYear / periods, medicare: medYear / periods, state: state, post: s.post };
    r.taxes = r.fed + r.ss + r.medicare + r.state;
    r.net = s.gross - k401 - pretax - r.taxes - s.post;
    return r;
  }
  // --- calc end

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var FIELDS = ['Gross', 'Status', 'Step2', 'Step3', 'Step4a', 'Step4b', 'Step4c', '401k', 'Pretax', 'Post', 'State'];

  function el(id) { return document.getElementById(id); }
  function num(id) { var v = parseFloat(el(id).value); return isNaN(v) ? NaN : v; }
  function set(id, text) { var e = el(id); if (e) e.textContent = text; }
  function fmt(v) { return money.format(Math.abs(v) < 0.005 ? 0 : v); }
  function signed(v) { if (Math.abs(v) < 0.005) return money.format(0); return (v < 0 ? '−' : '+') + money.format(Math.abs(v)); }
  function label(k) { var t = el('pdc' + k + 'Name').value.trim(); return t ? t.slice(0, 30) : 'Paycheck ' + k; }

  function read(k) {
    var p = 'pdc' + k, status = el(p + 'Status').value;
    return {
      gross: num(p + 'Gross'), status: STANDARD[status] ? status : 'single', step2: el(p + 'Step2').checked,
      step3: num(p + 'Step3'), step4a: num(p + 'Step4a'), step4b: num(p + 'Step4b'), step4c: num(p + 'Step4c'),
      k401Pct: num(p + '401k'), pretax: num(p + 'Pretax'), post: num(p + 'Post'), stateRate: num(p + 'State')
    };
  }
  function problem(s) {
    var vals = [s.gross, s.step3, s.step4a, s.step4b, s.step4c, s.k401Pct, s.pretax, s.post, s.stateRate];
    if (vals.some(function (v) { return !isFinite(v) || v < 0 || v > 1e9; }) || s.k401Pct > 100 || s.stateRate > 20) {
      return 'Enter amounts of $0 or more, a 401(k) rate from 0 to 100% and a state rate from 0 to 20%.';
    }
    if (s.gross * s.k401Pct / 100 + s.pretax + s.post > s.gross + 0.005) return 'The deductions add up to more than the gross pay.';
    return '';
  }

  function update() {
    var periods = parseInt(el('pdcFreq').value, 10);
    if (!(periods > 0)) periods = 26;
    var a = read('A'), b = read('B');
    var error = el('pdcError');
    var pa = problem(a), pb = problem(b);
    var msg = pa ? 'Paycheck A: ' + pa : (pb ? 'Paycheck B: ' + pb : '');
    error.hidden = !msg;
    if (msg) { error.textContent = msg; return; }

    var ra = paycheck(a, periods), rb = paycheck(b, periods);
    var nameA = label('A'), nameB = label('B');
    set('pdcNetALabel', 'Take-home, ' + nameA);
    set('pdcNetBLabel', 'Take-home, ' + nameB);
    set('pdcColA', nameA);
    set('pdcColB', nameB);
    set('pdcNetA', fmt(ra.net));
    set('pdcNetB', fmt(rb.net));
    set('pdcDiff', signed(rb.net - ra.net));
    set('pdcDiffYear', signed((rb.net - ra.net) * periods));

    var dNet = rb.net - ra.net, dSave = (rb.k401 - ra.k401), dTax = rb.taxes - ra.taxes, text;
    if (Math.abs(dNet) < 0.005) {
      text = 'Both paychecks leave you with the same take-home pay.';
    } else {
      text = nameB + (dNet > 0 ? ' gives you ' + fmt(dNet) + ' more' : ' leaves you ' + fmt(-dNet) + ' less') +
             ' take-home pay per paycheck (' + fmt(Math.abs(dNet) * periods) + ' a year).';
    }
    if (Math.abs(dSave) >= 0.005) {
      text += ' It puts ' + fmt(Math.abs(dSave)) + (dSave > 0 ? ' more' : ' less') + ' into your 401(k) each paycheck';
      if (dSave > 0 && dNet < 0 && -dNet < dSave - 0.005) {
        text += ', but take-home pay drops by only ' + fmt(-dNet) + ' because lower taxes cover ' + fmt(dSave + dNet) + ' of it';
      }
      text += '.';
    }
    if (Math.abs(dTax) >= 0.005) text += ' Taxes per paycheck ' + (dTax > 0 ? 'rise' : 'fall') + ' by ' + fmt(Math.abs(dTax)) + '.';
    set('pdcSummary', text);

    var k = el('pdcView').value === 'year' ? periods : 1;
    var rows = [
      ['Gross pay', 'gross', 1], ['401(k) / 403(b) contribution', 'k401', -1], ['Pre-tax benefits', 'pretax', -1],
      ['Federal income tax withheld', 'fed', -1], ['Social Security', 'ss', -1], ['Medicare', 'medicare', -1],
      ['State and local income tax', 'state', -1], ['After-tax deductions', 'post', -1], ['Take-home pay', 'net', 1]
    ];
    var body = el('pdcTable');
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (row, i) {
      var tr = document.createElement('tr');
      var last = i === rows.length - 1;
      var va = ra[row[1]] * k, vb = rb[row[1]] * k;
      var cells = [row[0], (row[2] < 0 && va >= 0.005 ? '−' : '') + fmt(va), (row[2] < 0 && vb >= 0.005 ? '−' : '') + fmt(vb), signed(row[2] * (vb - va))];
      cells.forEach(function (t, j) {
        var c = document.createElement(j === 0 ? 'th' : 'td');
        if (j === 0) c.setAttribute('scope', 'row');
        if (last) { var s = document.createElement('strong'); s.textContent = t; c.appendChild(s); } else c.textContent = t;
        tr.appendChild(c);
      });
      body.appendChild(tr);
    });
  }

  function copyAtoB() {
    FIELDS.forEach(function (f) {
      var src = el('pdcA' + f), dst = el('pdcB' + f);
      if (!src || !dst) return;
      if (src.type === 'checkbox') dst.checked = src.checked; else dst.value = src.value;
    });
    update();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('pdcForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('pdcView').addEventListener('change', update);
    el('pdcCopy').addEventListener('click', copyAtoB);
    update();
  });
})();
